// Self-contained interactive procedures. Commit costs onl andafter successful completion.
const baseChoose=choose;
choose=function(key,id){if(id==='water'){irrigation();return}if(id==='aim'){antennaGame();return}baseChoose(key,id)};
let stopMini=()=>{};
$('dialog').addEventListener('close',()=>{if(!$('dialog').open)stopMini()});
function miniFrame(title,description,content){stopMini();open(`<small>INTERACTIVE PROCEDURE</small><h2>${title}</h2><p>${description}</p>${content}<p id="miniStatus" role="status" aria-live="polite"></p><div class="buttons"><button data-close>Cancel without spending</button><button id="miniDone" class="primary" disabled>Apply result</button></div><p class="muted">Training simulation. See NASA Data for the geometry sources.</p>`)}
function irrigation(){if(!options(state,'food').find(o=>o.id==='water')?.enabled)return;
 miniFrame('Moisture radar',`Scan the plots. Red and orange mark dry plots, and blue marks wet plots. Water only the three dry plots. Use Tab to scan and Enter to water. Cost on completion:${state.irrigationUpgrade?5:6}  water, 2 energy.`,`<div class="farm"><div class="farmhead">AURORA / HYDROPONIC TRAY <span id="waterCount">0 / 3</span></div><div id="plots" class="plots"></div></div><div class="humidityLegend"><span>DRY</span><div><i id="humidityNeedle"></i></div><span>WET</span></div>`);
 // Fixed within the attempt; varies b andmission turn and crop, independent of pointer input.
 const offset=(state.day+state.crop.type.length)%12,dry=new Set([offset,(offset+4)%12,(offset+7)%12]),watered=new Set();
 for(let i=0;i<12;i++){const b=document.createElement('button');b.className='plot';b.innerHTML='<span class="seedlings">♧ ♧ ♧<br>♧ ♧ ♧</span><span class="scanner">⌖</span><small>PLOT '+(i+1)+'</small>';b.setAttribute('aria-label','Scan plot '+(i+1));const inspect=()=>{document.querySelectorAll('.plot').forEach(x=>x.classList.remove('scanned'));b.classList.add('scanned');const humidity=watered.has(i)?85:dry.has(i)?15:65+(i%4)*7;b.style.setProperty('--scan',humidity<30?'#f49253':'#52bce0');$('humidityNeedle').style.left=humidity+'%';$('miniStatus').textContent=`Plot ${i+1}: moisture ${humidity}%. ${humidity<30?'Dry. Click to water.':'Wet. No watering needed.'}`};b.onpointerenter=inspect;b.onfocus=inspect;b.onclick=()=>{inspect();if(!dry.has(i)||watered.has(i)){$('miniStatus').textContent='This plot has enough water. Look for a dry plot.';return}watered.add(i);b.classList.add('watered');b.setAttribute('aria-label','Plot '+(i+1)+'  watered');b.querySelector('.scanner').textContent='✓';inspect();$('waterCount').textContent=watered.size+' / 3';beep();if(watered.size===3){$('miniStatus').textContent='Three plots watered. Apply the result to add two days of moisture.';$('miniDone').disabled=false}};$('plots').append(b)}
 $('miniDone').onclick=()=>{stopMini();executeDecision('food','water')};stopMini=()=>{};
}
function antennaGame(){if(!options(state,'telecom').find(o=>o.id==='aim')?.enabled)return;
 miniFrame('Earth link','Drag across the sky or use ← and → to aim. Keep Earth within the beam for four seconds to lock the antenna. Earth reappears on the left if it crosses the edge before lock. The exercise uses a simulated path and applies the final calibration to the Horizons reference. Aiming is free. Transmitting costs energy.',`<canvas id="antennaSky" width="680" height="330" tabindex="0" aria-label="Antenna: use left and right arrows to track Earth"></canvas><div class="lockbar"><i id="lockProgress"></i></div><p id="antennaReadout"></p>`);
 const c=$('antennaSky'),g=c.getContext('2d'),held=new Set();let bearing=90,earth=70,elapsed=0,lock=0,previous=0,raf=0,done=false,active=true,lockedCalibration=null,dragging=false,position=antennaPosition(state,0),lastCycle=position.cycle;
 function point(e){if(done||!active)return;const r=c.getBoundingClientRect(),x=(e.clientX-r.left)*680/r.width,y=(e.clientY-r.top)*330/r.height;bearing=Math.max(10,Math.min(170,Math.atan2(300-y,x-340)*180/Math.PI))}
 c.onpointermove=e=>{if(dragging)point(e)};c.onpointerup=c.onpointercancel=()=>{dragging=false};c.onlostpointercapture=()=>{dragging=false};c.onpointerdown=e=>{if(done||!active)return;dragging=true;c.setPointerCapture(e.pointerId);point(e);c.focus()};c.onkeydown=e=>{if(done||!active)return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();held.add(e.key)}};c.onkeyup=e=>held.delete(e.key);c.onblur=()=>held.clear();
 const draw=t=>{if(!active||!$('dialog').open||!c.isConnected)return;const dt=Math.min((t-previous)/1000||0,.04);previous=t;if(!document.hidden){elapsed+=dt;if(!done){position=antennaPosition(state,elapsed);earth=position.angle;if(position.cycle!==lastCycle){lock=0;lastCycle=position.cycle;}bearing+=((held.has('ArrowLeft')?1:0)-(held.has('ArrowRight')?1:0))*65*dt;bearing=Math.max(10,Math.min(170,bearing));const error=Math.abs(bearing-earth);lock=error<9&&position.x>=25&&position.x<=655?Math.min(4,lock+dt):Math.max(0,lock-dt*1.5);if(lock>=4){done=true;lockedCalibration=Math.max(0,Math.min(180,target(state)+bearing-earth));held.clear();c.style.cursor='default';$('miniDone').textContent='Save locked alignment';$('miniDone').disabled=false;$('miniStatus').textContent='Alignment locked. Save to apply the calibration.';beep()}}}
 g.fillStyle='#071526';g.fillRect(0,0,680,330);for(let i=0;i<55;i++){g.fillStyle='#9ab7d2';g.fillRect(i*127%680,i*i*19%270,1.5,1.5)}
 g.strokeStyle='#31526c';g.lineWidth=1;g.setLineDash([5,8]);g.beginPath();g.ellipse(340,300,390,235,0,Math.PI,Math.PI*2);g.stroke();g.setLineDash([]);
 const angle=bearing*Math.PI/180,ex=position.x,ey=position.y;g.fillStyle='#8cebd21f';g.beginPath();g.moveTo(340,300);g.arc(340,300,280,-angle-.14,-angle+.14);g.closePath();g.fill();g.strokeStyle='#9bedda';g.lineWidth=3;g.beginPath();g.moveTo(340,300);g.lineTo(340+270*Math.cos(angle),300-270*Math.sin(angle));g.stroke();
 g.fillStyle='#397ab5';g.beginPath();g.arc(ex,ey,22,0,Math.PI*2);g.fill();g.fillStyle='#96d6b9';g.beginPath();g.ellipse(ex-5,ey-3,9,16,.6,0,7);g.ellipse(ex+11,ey+10,7,8,-.4,0,7);g.fill();g.strokeStyle='#d4f1ff';g.lineWidth=2;g.beginPath();g.arc(ex,ey,25,0,7);g.stroke();g.fillStyle='#b9d0dc';g.fillRect(332,290,16,35);g.save();g.translate(340,295);g.rotate(Math.PI/2-angle);g.beginPath();g.arc(0,0,25,0,Math.PI);g.fill();g.restore();
 $('lockProgress').style.width=lock/4*100+'%';$('antennaReadout').textContent=`Antenna ${bearing.toFixed(2)}° · Earth ${earth.toFixed(2)}° · Tracking ${(lock).toFixed(1)} / 4 s · Training path`;
 raf=requestAnimationFrame(draw)};
 stopMini=()=>{active=false;cancelAnimationFrame(raf);held.clear()};$('miniDone').onclick=()=>{if(!done)return;stopMini();executeDecision('telecom','aim',lockedCalibration)};raf=requestAnimationFrame(draw);c.focus();
}
